<script setup lang="ts">
definePageMeta({layout:false})
const email=ref(''),password=ref(''),busy=ref(false),error=ref('')
async function login(){error.value='';busy.value=true;try{await $fetch('/api/admin/login',{method:'POST',body:{email:email.value,password:password.value}});await navigateTo('/admin')}catch(e){error.value=humanError(e)}finally{busy.value=false}}
useSeoMeta({title:'ورود به پنل مدیریت | دکتر آزاده مهرداد',robots:'noindex,nofollow'})
</script>
<template><div class="min-h-screen grid lg:grid-cols-2 bg-[#f7faf7]"><div class="hidden lg:flex items-center justify-center bg-[#0c4d46] relative overflow-hidden"><div class="absolute w-[500px] h-[500px] rounded-full bg-white/5 -top-48 -right-44"></div><div class="relative z-10 max-w-md text-white p-12"><span class="w-16 h-16 grid place-items-center rounded-2xl bg-white/10 mb-8"><Icon name="smile" :size="39" /></span><h1 class="font-extrabold text-4xl leading-[1.7]">مدیریت هوشمند،<br />لبخندهای بیشتر.</h1><p class="text-[#c1ddd2] mt-5 leading-9 text-sm">برنامه‌ریزی نوبت‌ها، مدیریت خدمات و اطلاعات سایت در یک فضای امن و ساده.</p></div></div><div class="flex items-center justify-center p-6"><form class="glass-card p-8 md:p-12 w-full max-w-[465px]" @submit.prevent="login"><NuxtLink to="/" class="inline-flex items-center gap-2 text-[#749388] text-xs mb-10"><Icon name="arrow-right" :size="17" /> بازگشت به سایت</NuxtLink><span class="eyebrow">ورود اختصاصی پزشک</span><h2 class="text-[26px] font-extrabold text-jade-800 mt-3">خوش آمدید!</h2><p class="text-xs text-[#829c8e] mt-2 mb-9">برای ورود به داشبورد اطلاعات خود را وارد کنید.</p><div class="mb-5"><label class="field-label" for="email">ایمیل مدیریت</label><input id="email" v-model="email" type="email" class="input-field" dir="ltr" required autocomplete="username" placeholder="admin@example.com" /></div><div class="mb-6"><label class="field-label" for="password">رمز عبور</label><input id="password" v-model="password" type="password" class="input-field" dir="ltr" required autocomplete="current-password" placeholder="••••••••••" /></div><p v-if="error" class="bg-red-50 text-red-700 rounded-xl p-4 text-xs mb-5" role="alert">{{error}}</p><button :disabled="busy" class="btn-main w-full !py-4"><Icon :name="busy?'loader-circle':'lock-keyhole'" :class="busy?'animate-spin':''" :size="17" /> {{busy?'در حال بررسی...':'ورود امن به پنل'}}</button><p class="text-center text-[11px] text-[#9caf9f] mt-7">دسترسی فقط برای مدیر مجاز است.</p></form></div></div></template>
